/* Review drill: one fresh-numbers question from a solved mission. Order of choice: reviews that are
   due (most overdue first), open notebook entries, missions never reviewed, then the next one due. */
function pickReview(){const pool=state.solved.filter(id=>window.Variants?.has(id)),now=Date.now(),any=list=>list[Math.floor(Math.random()*list.length)];if(!pool.length)return null;
 const due=pool.filter(id=>reviewDue(id)&&reviewDue(id)<=now).sort((a,b)=>reviewDue(a)-reviewDue(b));if(due.length)return {id:due[0],why:'Due for review'};
 const flagged=pool.filter(openError).sort((a,b)=>state.errors[b].n-state.errors[a].n);if(flagged.length)return {id:flagged[0],why:'From your error notebook'};
 const unseen=pool.filter(id=>!state.reviews[id]);if(unseen.length)return {id:any(unseen),why:'First review'};
 return {id:pool.slice().sort((a,b)=>reviewDue(a)-reviewDue(b))[0],why:'Ahead of schedule'}}
function review(forceId){const choice=typeof forceId==='string'&&state.solved.includes(forceId)&&window.Variants?.has(forceId)?{id:forceId,why:'Your choice'}:pickReview();if(!choice)return;const q=byId.get(choice.id),v=Variants.make(q.id);activeVariant=v;
 open(`<div class="eyebrow">REVIEW DRILL / ${esc(q.id.toUpperCase())} · ${esc(q.topic)} · ${esc(choice.why.toUpperCase())}</div><h2>${esc(q.title)}, with new numbers</h2><div class="mission-panel"><p>${esc(v.setup)}</p><p><b>${esc(v.prompt)}</b> ${esc(v.note||'Answers within 2% are accepted.')}</p><div class="answer-grid"><div><label for="review-answer">${esc(v.label)}</label><input id="review-answer" type="text" inputmode="decimal" autocomplete="off"></div></div><div class="modal-actions"><button class="primary" id="review-check">Check ↗</button><button class="secondary" id="review-lesson">Open the lesson</button><button class="secondary" id="review-next">Another drill</button></div><div class="feedback" id="review-feedback" aria-live="polite"></div><p style="font-size:12px">Drills give no XP${coll()?'; a pass on the first check gives a little stardust':''}. A pass lengthens the gap before this concept returns (1, 3, 7, 16, 35, then 90 days); a miss brings it back tomorrow and logs it in your notebook.</p></div>`);
 activeVariant=v;let settled=false,stardust=0;$('#review-check').onclick=()=>{const input=$('#review-answer'),out=$('#review-feedback'),raw=readNumber(input.value,x=>Variants.check(v,x));if(!Number.isFinite(raw)){out.textContent='Enter a number first.';return}const ok=Variants.check(v,raw);if(!settled){if(!ok)recordError(q.id);recordReview(q.id,ok);/* A drill passed on its first check pays stardust, once. */if(ok)stardust=dustIn(drillDust())}settled=true;const days=REVIEW_DAYS[Math.min(Math.max(reviewCount(q.id),1),REVIEW_DAYS.length)-1];out.textContent=(ok?'Correct. ':'Not quite: '+v.label+' = '+Variants.show(v.target)+'. ')+v.formula+(ok?` Next review in ${days} day${days===1?'':'s'}.`:' Logged in your notebook; it returns tomorrow.')+(ok&&stardust?` +${stardust} stardust.`:'');$('#review-check').disabled=true};
 $('#review-lesson').onclick=()=>mission(q.id);$('#review-next').onclick=review}

